COMMENT ON COLUMN cca.competition_result.result_value IS 'time / distance / score';
COMMENT ON COLUMN cca.quran_milestone.code IS '''JUZ_30'', ''SURAH_YASIN''';
COMMENT ON COLUMN sec.pickup_authorisation.otp_hash IS 'adhoc: OTP / QR token';
COMMENT ON COLUMN sec.gate_event.cctv_ref IS 'SEC-04 NVR channel + timestamp for incident review';
COMMENT ON COLUMN prt.form_definition.schema IS 'JSON schema of fields';
